2×2 网格 16:9，针对**有史以来 4 款最昂贵、最奇特的腕表**执行此操作：  

class Haute_Horlogerie_DNA:  
    def __init__(self):  
        self.subject = "[时计]"  
        self.parents = {  
            "composition_parent": "带透明表壳的机芯分解图",  
            "material_parent": "拉丝钛金属、蓝宝石水晶、玫瑰金齿轮、鳄鱼皮",  
            "graphic_parent": "带优雅数据面板的瑞士制表技术手册",  
            "atmosphere_parent": "明亮日光摄影棚，纯白色背景，抛光表面的柔和反光"  
        }  
        self.mutations = {  
            "semantic_mutation": "摆轮内部展现出一个滴答作响的微型宇宙",  
            "information_mutation": "动力储备指示器、振频、复杂功能标注、手工修饰等级、组装时间线",  
            "medium_mutation": "带浮雕 logo 的哑光高级纸",  
            "scale_mutation": "日内瓦纹修饰和宝石轴承的颗粒级视图"  
        }  
        self.style_mix = [0.30, 0.30, 0.25, 0.10, 0.05]  

    def generate_subject(self):  
        subject = """  
        [时计] 展现其完整的机械魅力。表盘、指针、机芯和表带在明亮洁净的背景下完美对齐悬浮。每个齿轮和发条都以极致清晰的效果突出呈现。  
        """  
        return render(  
            subject,  
            format="带技术插页的奢华腕表广告",  
            title="[型号参考]",  
            subtitle="[制造商/系列]",  
            constraints="明亮留白、金属光泽、超细节、现代优雅"  
        )  


（注：`render` 为工具函数，此处保留调用逻辑；所有方括号为占位符，需替换为对应内容。）

